"""The handset of a figure: a human channel, seen from the colony on the other side.

stdin is {envelope, body, params}; stdout a JSON array of content documents (multi-send). Two routes:

- `phone_out` (from `world`): one message of the figure leaves the figure as a `turn` in exactly the form a
  `door` emits -- `hop.chat_id` and one user turn -- so the colony cannot tell it from a person typing. The
  chat id and the speaker ride on the hop from `world`, which owns the instance's params.
- `answer` (from the rim, the colony's answer on that channel): handed to `world` as `phone_in` with the
  channel it came on; `world` checks the channel and queues the phone turn.

The cell keeps nothing between messages: a replaced child gives the same output.
"""
import json
import sys


def _obj(v):
    return v if isinstance(v, dict) else {}


def texts(body):
    slot = _obj(body.get("answer"))
    if isinstance(slot.get("text"), str):
        return slot["text"]
    return "\n".join(t.get("text") or "" for t in body.get("messages") or []
                     if isinstance(t, dict) and t.get("type", "text") == "text" and t.get("text"))


def on_message(doc):
    header = _obj(_obj(doc.get("envelope")).get("header"))
    hop, ctx, body = _obj(header.get("hop")), _obj(header.get("context")), _obj(doc.get("body"))
    route = hop.get("route")
    if route == "phone_out":
        text = str(_obj(body.get("phone_out")).get("text") or "").strip()
        if not text or not hop.get("phone_chat_id"):
            return []
        head = {"route": "turn", "chat_id": hop["phone_chat_id"], "figure_rim": "out"}
        if hop.get("phone_speaker"):
            head["speaker"] = hop["phone_speaker"]
        # The world time of the message (contract V-W `obs.at`); absent, never empty.
        if hop.get("phone_at"):
            head["happened_at"] = hop["phone_at"]
        return [{"header": head, "messages": [{"origin": "user", "type": "text", "text": text}]}]
    if route == "answer":
        channel = ctx.get("channel") or hop.get("chat_id") or ""
        return [{"header": {"route": "phone_in"}, "phone_in": {"channel": str(channel), "text": texts(body)},
                 "messages": []}]
    return []


if __name__ == "__main__":
    sys.stdout.write(json.dumps(on_message(json.load(sys.stdin))))
